import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../core/app_controller.dart';
import '../models/models.dart';
import '../widgets/common.dart';

class OrdersScreen extends StatelessWidget{const OrdersScreen({super.key});Future<void>confirm(BuildContext context,int id)async{try{await context.read<AppController>().api.confirmReceived(id);await context.read<AppController>().refreshAll();if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم تسجيل استلام الطلب وإرسال التأكيد.')));}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}}
@override Widget build(BuildContext context){final app=context.watch<AppController>();return Scaffold(appBar:AppBar(title:const Text('طلباتي')),body:RefreshIndicator(onRefresh:app.refreshAll,child:ListView(padding:const EdgeInsets.all(12),children:[if(app.orders.isEmpty)const PageCard(child:Text('لا توجد طلبات حالياً.',textAlign:TextAlign.center)) else ...app.orders.map((o)=>Padding(padding:const EdgeInsets.only(bottom:8),child:PageCard(child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Row(children:[const Icon(Icons.local_shipping_outlined,color:AppColors.blue),const SizedBox(width:8),Expanded(child:Text(o.number,style:const TextStyle(fontWeight:FontWeight.w900))),Text(o.status,style:const TextStyle(fontSize:10,fontWeight:FontWeight.w800))]),const Divider(),Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text('${o.total.toStringAsFixed(2)} ${o.currency}',style:const TextStyle(fontWeight:FontWeight.w900)),Text(o.createdAt??'',style:const TextStyle(fontSize:9,color:Colors.black45))]),if(o.status=='delivered')Align(alignment:Alignment.centerLeft,child:OutlinedButton(onPressed:()=>confirm(context,o.id),child:const Text('تأكيد الاستلام')))]))))])));}}
